package org.eclipse.jdt.internal.ui.text;

public class JavaIndenter {
    private Prefs fPrefs;
    private int prevToken;

    static class Prefs {
        boolean prefIndentBracesForBlocks = false;
        boolean prefIndentBracesForArrays = false;
        boolean prefIndentBracesForMethods = false;
    }
    static class Symbols {
        public static final int TokenLBRACE = 1;
        public static final int TokenCOLON = 2;
        public static final int TokenEQUAL = 3;
        public static final int TokenRBRACKET = 4;
        public static final int TokenRPAREN = 5;
        public static final int TokenTRY = 6;
    }

    public void foo() {
        boolean bracelessBlockStart = false;
        boolean unindent = false;
        boolean indent = false;
        fPrefs = new Prefs();

        int token = Symbols.TokenLBRACE;
        switch (token) {
            case Symbols.TokenLBRACE:
                if (bracelessBlockStart && !fPrefs.prefIndentBracesForBlocks)
                    unindent = true;
                else if ((prevToken == Symbols.TokenCOLON || prevToken == Symbols.TokenEQUAL || prevToken == Symbols.TokenRBRACKET) && !fPrefs.prefIndentBracesForArrays)
                    unindent = true;
                else if (!bracelessBlockStart && fPrefs.prefIndentBracesForMethods)
                    indent = true;
                break;
        }
    }
}

